css:
/* Ebooks */
.ebs {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  margin: 0;
  padding: 0;
  list-style: none;
}
.ebs__g {
  padding: 22px 24px 18px 0;
  border-top: 1px solid var(--line);
}
.ebs__for {
  margin: 0 0 6px;
  color: var(--mist);
  font-size: .75rem;
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.site .ebs__i {
  display: block;
  padding: 14px 0;
  text-decoration: none;
}
.ebs__i + .ebs__i {
  border-top: 1px solid var(--line);
}
.ebs__n {
  display: block;
  font-size: clamp(1.375rem, 1vw + 1.15rem, 1.75rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -.01em;
  transition: color .2s ease;
}
.ebs__t {
  display: block;
  margin-top: 4px;
  color: var(--mist);
  font-size: .9375rem;
}
.ebs__go {
  display: inline-block;
  margin-top: 8px;
  color: var(--jade);
  font-size: .875rem;
  font-weight: 600;
}
.ebs__i:hover .ebs__n {
  color: var(--jade);
}
.ebs__note {
  margin: 0;
  padding-top: 18px;
  border-top: 1px solid var(--line);
  color: var(--mist);
  font-size: .875rem;
}
@media (min-width: 720px) {
  .ebs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1000px) {
  .ebs { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
